#include <stdio.h>

unsigned int digits(unsigned int n)
{
    if (n < 10) {
        return n;
    }
    return n % 10 + digits(n / 10);
}

int main(void)
{
    printf("%u\n", digits(409));
    return 0;
}

#include <stdio.h>

unsigned int gcd(unsigned int a, unsigned int b)
{
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}

int main(void)
{
    printf("%u\n", gcd(48, 18));
    return 0;
}

#include <stdio.h>

long long power(long long base, unsigned int exponent)
{
    if (exponent == 0) {
        return 1;
    }
    return base * power(base, exponent - 1);
}

int main(void)
{
    printf("%lld %lld\n", power(-2, 3), power(9, 0));
    return 0;
}

